package com.franco.desco.adapter.in.web.delivery;import com.franco.desco.application.delivery.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.delivery.DeliveryModels;import org.springframework.stereotype.Component;import java.time.LocalDate;
@Component public class DeliveryWebMapper{public DeliveryCommands.ListDeliveries list(int p,int t,Long op,Long socio,String estado,String calidad,LocalDate desde,LocalDate hasta){return new DeliveryCommands.ListDeliveries(new PageRequest<>(p,t,new DeliveryCommands.Filter(op,socio,estado,calidad,desde,hasta),null,null));}public java.util.List<DeliveryCommands.Line>lines(java.util.List<DeliveryRequests.Line>x){return x.stream().map(v->new DeliveryCommands.Line(v.variedadPaltaId(),v.condicionComercialId(),v.kilogramos())).toList();}public DeliveryResponses.Summary response(DeliveryModels.Summary x){return new DeliveryResponses.Summary(x.entregaSocioId(),x.codigoLote(),x.fechaHora(),x.pesoBrutoKg(),x.taraKg(),x.pesoRechazadoKg(),x.pesoAceptadoKg(),x.estadoControlCalidad(),x.estadoProceso(),x.operativoVentaId(),x.operativo(),x.socioId(),x.numeroDocumento(),x.socioNombre(),x.valorizacion());}public DeliveryResponses.Detail response(DeliveryModels.Detail x){var h=x.entrega();return new DeliveryResponses.Detail(new DeliveryResponses.Header(h.entregaSocioId(),h.codigoLote(),h.fechaHora(),h.pesoBrutoKg(),h.taraKg(),h.pesoNetoKg(),h.pesoRechazadoKg(),h.pesoAceptadoKg(),h.estadoControlCalidad(),h.ticketBalanza(),h.observacion(),h.estadoProceso(),h.predioId(),h.predioCodigo(),h.operativoVentaId(),h.operativo(),h.numeroDocumento(),h.socioNombre()),x.detalles().stream().map(d->new DeliveryResponses.DetailLine(d.entregaDetalleId(),d.variedadPaltaId(),d.variedad(),d.condicionComercialId(),d.condicion(),d.precioComercialId(),d.kilogramos(),d.precioBase(),d.precioAplicado(),d.importe())).toList(),x.incidencias().stream().map(i->new DeliveryResponses.Incident(i.incidenciaId(),i.tipoIncidencia(),i.severidad(),i.pesoAfectadoKg(),i.descripcion(),i.estadoIncidencia())).toList(),x.archivos().stream().map(f->new DeliveryResponses.File(f.archivoId(),f.nombreOriginal(),f.mimeType(),f.secureUrl(),f.categoria(),f.descripcion(),f.fechaCarga())).toList());}}
